      if (this.stun > 0) { ctx.fillStyle = '#f8d040'; const a = this.t * 8; ctx.fillRect(X + Math.cos(a) * 6, Y - 32, 2, 2); ctx.fillRect(X - Math.cos(a) * 6, Y - 32, 2, 2); }
