      if (p[1] === 'door' || p[1] === 'block-from') { const xy = p[2].split(','); w.setC(+xy[0], +xy[1], (w.def.plates || []).some(function (q) { return q[0] === +xy[0] && q[1] === +xy[1]; }) ? LV.C.PLATE : LV.C.OPEN); }
      if (p[1] === 'block-to') { const xy = p[2].split(','); w.setC(+xy[0], +xy[1], LV.C.BLOCK); }
