  ctx.fillStyle = '#e8eef8'; ctx.fillRect(x - 1, y, 2, 22); ctx.fillStyle = '#9aa8c0'; ctx.fillRect(x + 1, y + 2, 1, 20);
  ctx.fillStyle = '#4060c0'; ctx.fillRect(x - 9, y + 23, 18, 3); ctx.fillStyle = '#f0c040'; ctx.fillRect(x - 1, y + 23, 2, 3);
