      const air = this.ai === 'flyer' || this.ai === 'ambient' ? 6 + Math.round(Math.sin(this.t * 6) * 2) : this.ai === 'hopper' && this.hop > 0.3 ? Math.round(Math.sin((0.6 - this.hop) / 0.3 * Math.PI) * 6) : 0;
